import csv, json
scan = {int(r['item']): int(r['occurrences']) for r in csv.DictReader(open('notebook/scan_exact.csv'))}
det = {int(r['item']): float(r['overlap']) for r in csv.DictReader(open('notebook/detector_fast.csv'))}
print("scan rows", len(scan), "range", min(scan), max(scan), "contaminated", sum(v>0 for v in scan.values()))
print("det rows", len(det), "flagged>=0.5", sum(v>=0.5 for v in det.values()))
exact = {i for i,v in scan.items() if v>0}
cheap = {i for i,v in det.items() if v>=0.5}
print("cheap subset of exact:", cheap <= exact, "overlap", len(cheap & exact))
rows=[json.loads(l) for l in open('notebook/runs.jsonl') if l.strip()]
passes=[r for r in rows if r['svc']=='score' and r['model']=='M_new' and r['fmt']=='mc_letter' and r.get('detail')]
passes.sort(key=lambda r:r['config']['seed'])
print("passes", len(passes), [r['config']['seed'] for r in passes])
def compute(dirty):
    counts=[]
    for r in passes:
        acc={}
        for x in r['detail']:
            if x['item'] in dirty: continue
            c=acc.setdefault(x['slice'],[0,0,0]); c[0]+=1; c[1]+=x['scored']; c[2]+=x['correct']
        counts.append(acc)
    rates={s: round(sum(c[s][2]/c[s][0] for c in counts)/len(counts),6) for s in sorted(counts[0])}
    sizes={s:counts[0][s][0] for s in rates}
    tot=sum(sizes.values())
    micro=sum(rates[s]*sizes[s]/tot for s in rates)
    return rates,sizes,micro
for name,d in [('cheap',cheap),('exact',exact)]:
    rates,sizes,micro=compute(d)
    print(name, rates, sizes, "micro=%.6f"%micro)
    # release aggregation over w0
    vals=[]
    for w0 in (0.15,0.85):
        v=w0*rates[0]+(1-w0)*(2/3*rates[1]+1/3*rates[2]); vals.append(v)
    print("  release w0=0.15: %.6f  w0=0.85: %.6f"%tuple(vals))
# sanity: does any item have correct but not scored?
bad=sum(1 for r in passes for x in r['detail'] if x['correct'] and not x['scored'])
print("correct-but-unscored rows:", bad)
# dirty stats on M_new
r=passes[0]
for name,d in [('exact',exact)]:
    di=[x for x in r['detail'] if x['item'] in d]; cl=[x for x in r['detail'] if x['item'] not in d]
    print(name,"dirty acc", sum(x['correct'] for x in di)/len(di), "clean acc", sum(x['correct'] for x in cl)/len(cl))
EOF

